package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector.ebeMultiply(double[] v)
 */
public class OpenMapRealVector_ebeMultiply_TriageGen2Test {

    @Test
    public void testEbeMultiply_StandardCase() {
        // Setup a sparse vector: [1.0, 0.0, 2.0, 0.0, 3.0]
        OpenMapRealVector vector = new OpenMapRealVector(5);
        vector.setEntry(0, 1.0);
        vector.setEntry(2, 2.0);
        vector.setEntry(4, 3.0);

        // Multiplier array: [10.0, 5.0, 2.0, 1.0, 0.5]
        double[] v = {10.0, 5.0, 2.0, 1.0, 0.5};

        // Expected result: [1.0*10.0, 0.0, 2.0*2.0, 0.0, 3.0*0.5] = [10.0, 0.0, 4.0, 0.0, 1.5]
        OpenMapRealVector result = vector.ebeMultiply(v);

        Assert.assertEquals(5, result.getDimension());
        Assert.assertEquals(10.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(1), 1e-10);
        Assert.assertEquals(4.0, result.getEntry(2), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(3), 1e-10);
        Assert.assertEquals(1.5, result.getEntry(4), 1e-10);
    }

    @Test
    public void testEbeMultiply_AllZeros() {
        OpenMapRealVector vector = new OpenMapRealVector(3);
        vector.setEntry(0, 5.0);
        vector.setEntry(1, 10.0);
        vector.setEntry(2, 15.0);

        double[] v = {0.0, 0.0, 0.0};

        OpenMapRealVector result = vector.ebeMultiply(v);

        Assert.assertEquals(0.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(1), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(2), 1e-10);
    }

    @Test
    public void testEbeMultiply_EmptySparseVector() {
        // Vector with no non-zero entries
        OpenMapRealVector vector = new OpenMapRealVector(10);
        double[] v = new double[10];
        for (int i = 0; i < 10; i++) {
            v[i] = i + 1.0;
        }

        OpenMapRealVector result = vector.ebeMultiply(v);

        Assert.assertEquals(10, result.getDimension());
        // Sparsity should remain 0 (or very close to it)
        Assert.assertEquals(0.0, result.getL1Distance(new OpenMapRealVector(10)), 1e-10);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeMultiply_DimensionMismatch() {
        OpenMapRealVector vector = new OpenMapRealVector(5);
        vector.setEntry(0, 1.0);

        // Array size 3 does not match vector dimension 5
        double[] v = {1.0, 2.0, 3.0};

        vector.ebeMultiply(v);
    }

    @Test
    public void testEbeMultiply_Immutability() {
        // Ensure the original vector is not modified
        OpenMapRealVector vector = new OpenMapRealVector(2);
        vector.setEntry(0, 2.0);
        vector.setEntry(1, 4.0);

        double[] v = {0.5, 0.5};
        OpenMapRealVector result = vector.ebeMultiply(v);

        // Check result
        Assert.assertEquals(1.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(2.0, result.getEntry(1), 1e-10);

        // Check original
        Assert.assertEquals(2.0, vector.getEntry(0), 1e-10);
        Assert.assertEquals(4.0, vector.getEntry(1), 1e-10);
    }

    @Test
    public void testEbeMultiply_WithNegativeValues() {
        OpenMapRealVector vector = new OpenMapRealVector(2);
        vector.setEntry(0, -2.0);
        vector.setEntry(1, 3.0);

        double[] v = {2.0, -1.0};

        OpenMapRealVector result = vector.ebeMultiply(v);

        Assert.assertEquals(-4.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(-3.0, result.getEntry(1), 1e-10);
    }
}
